import json

def solve():
    houses = [1, 2, 3, 4, 5]

    categories = {
        "Name": ["Alice", "Peter", "Bob", "Eric", "Arnold"],
        "Smoothie": ["lime", "dragonfruit", "desert", "watermelon", "cherry"],
        "Animal": ["horse", "dog", "bird", "fish", "cat"],
        "Nationality": ["german", "swede", "norwegian", "brit", "dane"],
    }

    # Build variable keys
    vars_list = []
    for cat, vals in categories.items():
        for v in vals:
            vars_list.append(f"{cat}:{v}")

    # Helper to parse key
    def parse_key(k):
        cat, val = k.split(":", 1)
        return cat, val

    # Priority order to reduce search (put heavily constrained ones first)
    priority = [
        "Animal:horse",
        "Nationality:dane",
        "Animal:dog",
        "Smoothie:desert",
        "Smoothie:lime",
        "Nationality:swede",
        "Nationality:brit",
        "Name:Bob",
        "Animal:bird",
        "Smoothie:watermelon",
        "Name:Eric",
        "Animal:cat",
        "Name:Peter",
        "Smoothie:cherry",
        "Name:Alice",
        "Nationality:norwegian",
        # Remaining will be appended automatically
    ]
    # Create ordered variable list
    ordered_vars = []
    seen = set()
    for k in priority:
        if k in vars_list and k not in seen:
            ordered_vars.append(k)
            seen.add(k)
    for k in vars_list:
        if k not in seen:
            ordered_vars.append(k)
            seen.add(k)

    # Constraints helpers
    def get_pos(assn, key):
        return assn.get(key, None)

    def check_all_diff(assn):
        # For each category, assigned values must be at distinct houses
        for cat, vals in categories.items():
            seen_houses = set()
            for v in vals:
                key = f"{cat}:{v}"
                if key in assn:
                    h = assn[key]
                    if h in seen_houses:
                        return False
                    seen_houses.add(h)
        return True

    def check_equal(assn, k1, k2):
        p1 = get_pos(assn, k1)
        p2 = get_pos(assn, k2)
        if p1 is not None and p2 is not None:
            return p1 == p2
        return True

    def check_fixed(assn, k, h):
        p = get_pos(assn, k)
        if p is None:
            return True
        return p == h

    def check_left_of(assn, k_left, k_right):
        pL = get_pos(assn, k_left)
        pR = get_pos(assn, k_right)
        if pL is not None and pR is not None:
            return (pL + 1) == pR
        if pL is not None and pR is None:
            # left must be in 1..4
            if not (1 <= pL <= 4):
                return False
        if pL is None and pR is not None:
            # right must be in 2..5
            if not (2 <= pR <= 5):
                return False
        return True

    def check_two_between(assn, k1, k2):
        # There are two houses between -> abs diff == 3
        p1 = get_pos(assn, k1)
        p2 = get_pos(assn, k2)
        if p1 is not None and p2 is not None:
            return abs(p1 - p2) == 3
        if p1 is not None and p2 is None:
            # From p1, must have a partner at p1 +/- 3 within 1..5
            return (p1 - 3 >= 1) or (p1 + 3 <= 5)
        if p1 is None and p2 is not None:
            return (p2 - 3 >= 1) or (p2 + 3 <= 5)
        return True

    def check_right_of(assn, k_right, k_left):
        # k_right is somewhere to the right of k_left: position strictly greater
        pR = get_pos(assn, k_right)
        pL = get_pos(assn, k_left)
        if pR is not None and pL is not None:
            return pR > pL
        if pR is not None and pL is None:
            # right cannot be 1
            if pR == 1:
                return False
        if pR is None and pL is not None:
            # left cannot be 5
            if pL == 5:
                return False
        return True

    def is_consistent(assn):
        # All-different within categories
        if not check_all_diff(assn):
            return False

        # Clue constraints:
        # 1. The Swedish person is directly left of the dog owner.
        if not check_left_of(assn, "Nationality:swede", "Animal:dog"):
            return False

        # 2. There are two houses between the dog owner and the British person.
        if not check_two_between(assn, "Animal:dog", "Nationality:brit"):
            return False

        # 3. The Dane is the person who keeps horses.
        if not check_equal(assn, "Nationality:dane", "Animal:horse"):
            return False

        # 4. The bird keeper is somewhere to the right of the cat lover.
        if not check_right_of(assn, "Animal:bird", "Animal:cat"):
            return False

        # 5. The dog owner is directly left of the person who drinks Lime smoothies.
        if not check_left_of(assn, "Animal:dog", "Smoothie:lime"):
            return False

        # 6. Eric is the cat lover.
        if not check_equal(assn, "Name:Eric", "Animal:cat"):
            return False

        # 7. Bob is the bird keeper.
        if not check_equal(assn, "Name:Bob", "Animal:bird"):
            return False

        # 8. The person who likes Cherry smoothies is directly left of Peter.
        if not check_left_of(assn, "Smoothie:cherry", "Name:Peter"):
            return False

        # 9. The bird keeper is the Watermelon smoothie lover.
        if not check_equal(assn, "Animal:bird", "Smoothie:watermelon"):
            return False

        # 10. The Desert smoothie lover is the dog owner.
        if not check_equal(assn, "Smoothie:desert", "Animal:dog"):
            return False

        # 11. The person who keeps horses is in the third house.
        if not check_fixed(assn, "Animal:horse", 3):
            return False

        # 12. The Norwegian is Alice.
        if not check_equal(assn, "Nationality:norwegian", "Name:Alice"):
            return False

        return True

    # Domains: start with all 1..5 per var; for some, restrict directly
    def domain_for(var, assn):
        cat, val = parse_key(var)
        # Start with all houses
        dom = set(houses)

        # All-different within same category: eliminate houses already used in this category
        for v in categories[cat]:
            k = f"{cat}:{v}"
            if k in assn:
                dom.discard(assn[k])

        # Hard domain pruning for fixed positions
        if var == "Animal:horse":
            dom = {3}
        if var == "Nationality:dane":
            # Must be same as horse (which is 3 by clue 11)
            dom = {3}

        # For adjacency constraints, we won't further prune domain deeply here; consistency check handles most pruning.

        return sorted(dom)

    solution = {}

    def backtrack(idx, assn):
        nonlocal solution
        if idx == len(ordered_vars):
            if is_consistent(assn):
                solution = dict(assn)
                return True
            return False

        var = ordered_vars[idx]
        # Try domain values
        for h in domain_for(var, assn):
            assn[var] = h
            if is_consistent(assn):
                if backtrack(idx + 1, assn):
                    return True
            del assn[var]
        return False

    # Seed with nothing; backtracking will assign respecting fixed constraints
    backtrack(0, {})

    if not solution:
        raise RuntimeError("No solution found")

    # Build output rows per house
    header = ["House", "Name", "Smoothie", "Animal", "Nationality"]

    def value_at(category, house):
        for v in categories[category]:
            if solution.get(f"{category}:{v}") == house:
                return v
        return None

    rows = []
    for h in houses:
        row = [
            str(h),
            value_at("Name", h),
            value_at("Smoothie", h),
            value_at("Animal", h),
            value_at("Nationality", h),
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
